
import streamlit as st

from dashboard.common import (
    AMBER,
    TAUPE,
    WALNUT,
    EXPORT_DIR,
    inject_styles,
    load_csv,
    page_header,
    show_kpi,
)

st.set_page_config(
    page_title="Reports & Exports",
    page_icon="📁",
    layout="wide",
)

inject_styles()
page_header(
    "Reports & Exports",
    "Browse, preview, and download the datasets generated by the pipeline.",
)

EXPORTS = {
    "Country Verification": "country_verification.csv",
    "High-Risk Sellers": "high_risk_sellers.csv",
    "Industry Revenue": "industry_revenue.csv",
    "Monthly Registrations": "monthly_registrations.csv",
    "Data Quality Report": "quality_report.csv",
    "Refund Rates": "refund_rate.csv",
    "Revenue by Business Type": "revenue_by_business.csv",
    "Revenue by Country": "revenue_by_country.csv",
    "Total Sellers": "total_sellers.csv",
    "Verification Status": "verification_status.csv",
}

available_exports = {
    title: filename
    for title, filename in EXPORTS.items()
    if (EXPORT_DIR / filename).exists()
}

missing_exports = [
    filename
    for filename in EXPORTS.values()
    if not (EXPORT_DIR / filename).exists()
]

if not available_exports:
    st.error("No exports were found. Run the data pipeline first.")
    st.stop()

if missing_exports:
    st.warning(
        "Some expected exports are missing. Run the pipeline to regenerate them."
    )
    st.write("Missing files:", ", ".join(missing_exports))

selected_title = st.selectbox(
    "Select a report",
    options=list(available_exports.keys()),
)

filename = available_exports[selected_title]
data = load_csv(filename)

if data is None:
    st.error("The selected export could not be loaded.")
    st.stop()

row_count, column_count = data.shape
file_path = EXPORT_DIR / filename
file_size_kb = file_path.stat().st_size / 1024

kpis = st.columns(3)
show_kpi(kpis[0], "Records", f"{row_count:,}", WALNUT)
show_kpi(kpis[1], "Columns", f"{column_count:,}", AMBER)
show_kpi(kpis[2], "File Size", f"{file_size_kb:.2f} KB", TAUPE)

st.divider()

st.subheader(selected_title)
st.caption(f"File: dashboard/exports/{filename}")

search_term = st.text_input(
    "Search within this report",
    placeholder="Enter a value to filter rows...",
)

filtered_data = data.copy()

if search_term.strip():
    mask = filtered_data.astype(str).apply(
        lambda column: column.str.contains(
            search_term.strip(),
            case=False,
            regex=False,
            na=False,
        )
    ).any(axis=1)

    filtered_data = filtered_data[mask]

st.caption(
    f"Showing {len(filtered_data):,} of {row_count:,} records."
)

st.dataframe(
    filtered_data,
    width="stretch",
    hide_index=True,
)

st.download_button(
    label=f"Download {filename}",
    data=data.to_csv(index=False).encode("utf-8"),
    file_name=filename,
    mime="text/csv",
)

st.info(
    "Downloads contain the complete selected report, even when a search "
    "filter is active. The reports reflect the most recent pipeline exports."
)
